def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    me = [h[0] for h in history]
    op = [h[1] for h in history]

    op_c = 0
    for x in op:
        if x == 'C':
            op_c += 1
    op_rate = op_c / n

    s10 = n - 10
    if s10 < 0:
        s10 = 0
    c10 = 0
    l10 = n - s10
    for x in op[s10:]:
        if x == 'C':
            c10 += 1
    r10_rate = c10 / l10

    s20 = n - 20
    if s20 < 0:
        s20 = 0
    c20 = 0
    l20 = n - s20
    for x in op[s20:]:
        if x == 'C':
            c20 += 1
    r20_rate = c20 / l20

    last_op = op[-1]
    run = 0
    for x in reversed(op):
        if x == last_op:
            run += 1
        else:
            break

    CC = 0.0
    CD = 0.0
    DC = 0.0
    DD = 0.0
    recent_start = n - 30
    for i in range(1, n):
        w = 1.0
        if i > recent_start:
            w = 2.0
        pm = me[i - 1]
        co = op[i]
        if pm == 'C':
            if co == 'C':
                CC += w
            else:
                CD += w
        else:
            if co == 'C':
                DC += w
            else:
                DD += w

    total_D = DC + DD
    total_C = CC + CD
    pD = (DC + 1.0) / (total_D + 2.0)
    pC = (CC + 1.0) / (total_C + 2.0)

    if me[-1] == 'C':
        p_base = pC
    else:
        p_base = pD
    p_now = 0.55 * p_base + 0.25 * op_rate + 0.20 * r10_rate

    retal = pC - pD
    remaining = 100 - n
    if remaining > 35:
        w_factor = 5.0
    else:
        w_factor = 1.0 + (remaining / 35.0) * 4.0

    benefit = 1.0 + p_now
    penalty = 0.0
    if retal > 0.0:
        penalty = retal * w_factor

    allD_like = False
    if n >= 5 and op_c == 0:
        allD_like = True
    elif r10_rate <= 0.15:
        allD_like = True
    elif op_rate <= 0.18 and n >= 10:
        allD_like = True
    elif r20_rate <= 0.25 and op_rate < 0.35:
        allD_like = True

    if allD_like:
        return 'D'

    if run >= 5 and r10_rate <= 0.55:
        return 'D'

    generous = (total_D >= 1.0 and pD >= 0.62) or (DC >= 1.0 and DD < 0.5 and op_rate > 0.45)
    independent = (total_D >= 2.0 and abs(retal) < 0.16 and pD > 0.38 and op_rate > 0.30)
    retaliatory = (total_D >= 2.0 and pD <= 0.45) or (DD >= 1.5 and DC <= 0.5 and pC > 0.60)

    if me[-1] == 'D' and op[-1] == 'D':
        if run <= 4 and op_rate > 0.45 and r10_rate > 0.25:
            return 'C'

    if op[-1] == 'D' and run >= 4 and total_D < 2.0 and op_rate > 0.62 and r10_rate > 0.52:
        return 'C'

    if n >= 96:
        if allD_like or r10_rate <= 0.25 or pD <= 0.28:
            return 'D'
        if generous or independent or pD >= 0.55:
            return 'D'
        if retaliatory or (retal > 0.32 and pD < 0.55):
            return 'C'
        if op_c >= n - 1:
            if rng.random() < 0.10:
                return 'D'
        if p_now > 0.70 and total_D < 1.0:
            if rng.random() < 0.04:
                return 'D'
        return 'C'

    if benefit > penalty + 0.70:
        return 'D'

    if benefit > penalty:
        if rng.random() < 0.75:
            return 'D'
        return 'C'

    if op_rate > 0.60 and r10_rate > 0.50 and not generous and not independent:
        prob = 0.04 + 0.10 * (n / 100.0)
        if op_c >= n - 1:
            prob += 0.08
        if total_D < 2.0:
            prob += 0.02
        if total_D >= 1.0 and pD < 0.45:
            prob *= 0.15
        if prob > 0.15:
            prob = 0.15
        if rng.random() < prob:
            return 'D'

    return 'C'
